try {
    // Setting boolean variables
    ZT.log("Calculating boolean variables for specialties with special flows");
    const needs_aba = is_aba ? 1 : 0;
    const needs_fce = is_fce ? "true" : "false";
    const needs_blood_flow_restriction = is_blood_flow_restriction ? "true" : "false";
    const needs_dry_needling = is_dry_needling ? "true" : "false";
    const needs_telehealth = is_telehealth ? "true" : "false";
    const is_mva = is_motor_vehicle_accident ? "true" : "false";
    const is_wc = is_work_comp ? "true" : "false";

    //Setting the specialty needed, the specialty needed names and therapy type
    ZT.log("Setting the therapy type, the specialties needed and their names");
    const specialty_needed = [];
    const specialty_needed_name = [];
    const therapy_type = [];
    const therapy_service = [];
    const non_therapy_service = [];

    if (is_pt) {
        specialty_needed_name.push("None");
        therapy_service.push("Physical Therapy");
        specialty_needed.push("pt");
        if (is_pt && !therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_aba) {
        specialty_needed_name.push("None");
        specialty_needed.push("none");
        therapy_type.push("ABA");
    }
    if (is_speech) {
        specialty_needed_name.push("None");
        specialty_needed.push("none");
        therapy_type.push("Speech");
    }
    if (is_ot) {
        specialty_needed_name.push("OT");
        therapy_service.push("Occupational Therapy");
        specialty_needed.push("ot");
        if (!therapy_type.includes("OT")) therapy_type.push("OT");
    }
    if (is_motor_vehicle_accident) {
        specialty_needed_name.push("MVA");
        non_therapy_service.push("MVA");
        if (!specialty_needed.includes("pt")) specialty_needed.push("pt");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_work_comp) {
        specialty_needed_name.push("Work Comp");
        non_therapy_service.push("Work Comp");
        specialty_needed.push("work_comp");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_aquatic_therapy) {
        specialty_needed_name.push("Aquatic Therapy");
        therapy_service.push("Aquatic Therapy");
        specialty_needed.push("aquatic_therapy");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_bells_palsy) {
        specialty_needed_name.push("Bells Palsy");
        non_therapy_service.push("Bells Palsy");
        specialty_needed.push("bells_palsy");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_blood_flow_restriction) {
        specialty_needed_name.push("Blood Flow Restriction");
        non_therapy_service.push("Blood Flow Restriction");
        specialty_needed.push("blood_flow_restriction");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_concussion) {
        specialty_needed_name.push("Concussion");
        non_therapy_service.push("Concussion");
        specialty_needed.push("concussion");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_dry_needling) {
        specialty_needed_name.push("Dry Needling");
        non_therapy_service.push("Dry Needling");
        specialty_needed.push("dry_needling");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_fce) {
        specialty_needed_name.push("Functional Capacity Evaluation");
        non_therapy_service.push("Functional Capacity Evaluation");
        specialty_needed.push("functional_capacity_evaluation");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_lsvt_big) {
        specialty_needed_name.push("LSVT BIG");
        non_therapy_service.push("LSVT BIG");
        specialty_needed.push("lsvt_big");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_lymphedema) {
        specialty_needed_name.push("Lymphedema");
        non_therapy_service.push("Lymphedema");
        specialty_needed.push("lymphedema");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    
    if (is_mckenzie_method) {
        specialty_needed_name.push("Mckenzie Method");
        non_therapy_service.push("Mckenzie Method");
        specialty_needed.push("mckenzie_method");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_pelvic_floor_female) {
        specialty_needed_name.push("Pelvic Floor Female");
        non_therapy_service.push("Pelvic Floor Female");
        specialty_needed.push("pelvic_floor_female");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_pelvic_floor_male) {
        specialty_needed_name.push("Pelvic Floor Male");
        non_therapy_service.push("Pelvic Floor Male");
        specialty_needed.push("pelvic_floor_male");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_schroth_method) {
        specialty_needed_name.push("Schroth Method");
        non_therapy_service.push("Schroth Method");
        specialty_needed.push("schroth_method");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_telehealth) {
        specialty_needed_name.push("Telehealth");
        non_therapy_service.push("Telehealth");
        specialty_needed.push("telehealth");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_toe_walking) {
        specialty_needed_name.push("Toe Walking");
        non_therapy_service.push("Toe Walking");
        specialty_needed.push("toe_walking");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_torticollis) {
        specialty_needed_name.push("Torticollis");
        non_therapy_service.push("Torticollis");
        specialty_needed.push("torticollis");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_vertigo) {
        specialty_needed_name.push("Vertigo");
        non_therapy_service.push("Vertigo");
        specialty_needed.push("vertigo");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }
    if (is_vestibular) {
        specialty_needed_name.push("Vestibular");
        non_therapy_service.push("Vestibular");
        specialty_needed.push("vestibular");
        if (!therapy_type.includes("PT")) therapy_type.push("PT");
    }

    //Set wording for when it is offered or not
    const therapy_service_len = therapy_service.length;
    const non_therapy_service_len = non_therapy_service.length;
    let service_msg_offered = '';
    let service_msg_non_offered = '';

    if (therapy_service_len !== 0) {
        const therapy_msg = therapy_service_len === 1 ?
            therapy_service[0] :
            `${therapy_service.slice(0, therapy_service_len - 1).join(', ')} & ${therapy_service[therapy_service_len - 1]}`;
        service_msg_offered += therapy_msg;
        service_msg_non_offered += therapy_msg;
    }
    if (non_therapy_service_len !== 0) {
        const non_therapy_msg = non_therapy_service_len === 1 ?
            non_therapy_service[0] :
            `${non_therapy_service.slice(0, non_therapy_service_len - 1).join(', ')} & ${non_therapy_service[non_therapy_service_len - 1]}`;
        service_msg_offered += service_msg_offered === '' ? `therapy for ${non_therapy_msg}` : ` and therapy for ${non_therapy_msg}`;
        service_msg_non_offered += service_msg_non_offered === '' ? `therapy for ${non_therapy_msg}` : ` nor therapy for ${non_therapy_msg}`;
    }

    ZT.log("Setting the variables needed for the workflows");
    ZT.setFormData("specialty_needed_name", specialty_needed_name.join(", "));
    ZT.setFormData("specialty_needed", specialty_needed.join(","));
    ZT.setFormData("specialty_needed_name_offered", service_msg_offered);
    ZT.setFormData("specialty_needed_name_not_offered", service_msg_non_offered);
    ZT.setFormData("therapy_type", therapy_type.join(","));
    ZT.setFormData("needs_aba", needs_aba);
    ZT.setFormData("needs_fce", needs_fce);
    ZT.setFormData("needs_blood_flow_restriction", needs_blood_flow_restriction);
    ZT.setFormData("needs_dry_needling", needs_dry_needling);
    ZT.setFormData("needs_telehealth", needs_telehealth);
    ZT.setFormData("is_mva", is_mva);
    ZT.setFormData("is_wc", is_wc);
}
catch (ex) {
    ZT.log("Error during variable setup in specialty selection: " + ex);
}

